<?php $title='Online Orders';$h=static function($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');};ob_start(); ?>
<div class="d-flex align-items-center justify-content-between mb-3"><div><h3 class="mb-1">Online Orders</h3><p class="text-muted mb-0">Prepare, track, and collect payment for online pickup orders.</p></div><a class="btn btn-outline-primary" href="<?= url('?route=admin/online_orders') ?>">Refresh</a></div>
<form class="d-flex flex-wrap gap-2 mb-3" method="get" action="<?= url('') ?>"><input type="hidden" name="route" value="admin/online_orders"><label for="tracking-search" class="visually-hidden">Find tracking number</label><input id="tracking-search" name="tracking" class="form-control" style="max-width:320px" placeholder="Enter a tracking number" value="<?= $h($tracking) ?>"><button class="btn btn-outline-primary" type="submit">Find order</button></form>
<div class="alert alert-primary">Complete these orders here. Stock was already reserved at checkout; do not enter them again as new POS sales.</div>
<?php if($selected): ?><div class="card"><div class="card-body"><div class="d-flex justify-content-between flex-wrap gap-2"><h4><?= $h($selected['tracking_number']) ?></h4><span class="badge bg-primary"><?= $h(ucfirst($selected['status'])) ?></span></div><p><?= $h($selected['customer_name']) ?> · <?= $h($selected['phone']) ?> · <?= $h($selected['branch_name']) ?></p><div class="table-responsive"><table class="table"><thead><tr><th>Product</th><th>Quantity</th><th>Amount</th></tr></thead><tbody><?php foreach($selected['items'] as $item): ?><tr><td><?= $h($item['product_name']) ?></td><td><?= (int)$item['quantity'] ?></td><td>₱<?= number_format($item['line_total'],2) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="fw-bold">Total: ₱<?= number_format($selected['total'],2) ?> · Payment: <?= $h($selected['payment_status']) ?></p>
<form method="post" action="<?= url('?route=admin/online_orders') ?>" class="d-flex flex-wrap gap-2 align-items-center"><input type="hidden" name="csrf_token" value="<?= csrf_token() ?>"><input type="hidden" name="order_id" value="<?= (int)$selected['id'] ?>"><input type="hidden" name="tracking" value="<?= $h($selected['tracking_number']) ?>"><?php if($selected['status']==='pending'): ?><button class="btn btn-primary" name="status" value="preparing">Start preparing</button><?php if(User::has_permission($_SESSION['user']['id'],'refund_sales')||User::has_permission($_SESSION['user']['id'],'manage_inventory')): ?><button class="btn btn-outline-danger" name="status" value="cancelled">Cancel and release stock</button><?php endif; ?><?php elseif($selected['status']==='preparing'): ?><button class="btn btn-primary" name="status" value="ready">Mark ready for pickup</button><?php elseif($selected['status']==='ready'): ?><label for="payment-method" class="mb-0">Payment received by</label><select id="payment-method" class="form-select w-auto" name="payment_method"><?php foreach(['Cash','GCash','Maya','Card','Bank Transfer'] as $method): ?><option><?= $method ?></option><?php endforeach; ?></select><button class="btn btn-success" name="status" value="completed">Confirm payment and pickup</button><?php endif; ?></form><div class="mt-4"><h5>Progress</h5><?php foreach($selected['events'] as $event): ?><p class="small mb-1"><?= $h($event['created_at']) ?> · <?= $h($event['note']) ?></p><?php endforeach; ?></div></div></div><?php endif; ?>
<div class="card"><div class="card-body p-3"><div class="table-responsive"><table id="online-orders-table" class="table table-hover align-middle"><thead><tr><th>Tracking number</th><th>Customer</th><th>Branch</th><th>Status</th><th>Payment</th><th>Total</th><th>Ordered</th></tr></thead><tbody><?php foreach($orders as $order): ?><tr><td><a class="fw-semibold" href="<?= url('?route=admin/online_orders&tracking='.rawurlencode($order['tracking_number'])) ?>"><?= $h($order['tracking_number']) ?></a></td><td><?= $h($order['customer_name']) ?></td><td><?= $h($order['branch_name']) ?></td><td><?= $h(ucfirst($order['status'])) ?></td><td><?= $h(ucfirst($order['payment_status'])) ?></td><td>₱<?= number_format($order['total'],2) ?></td><td><?= $h($order['created_at']) ?></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="7" class="text-center text-muted py-4">No online orders yet.</td></tr><?php endif; ?></tbody></table></div></div></div>
<script>document.addEventListener('DOMContentLoaded',function(){if(window.jQuery&&jQuery.fn.DataTable&&<?= $orders?'true':'false' ?>){jQuery('#online-orders-table').DataTable({pageLength:10,order:[],language:{search:'Find in list:',lengthMenu:'Show _MENU_ orders'}});}});</script>
<?php $content=ob_get_clean();require __DIR__.'/../layouts/admin.php'; ?>
